const User = require('../../models/userModel');
const jwt = require('jsonwebtoken');

class UserFactory {
    static async create(overrides = {}) {
        const defaultData = {
            name: `Test User ${Date.now()}`,
            email: `user${Date.now()}@test.com`,
            matricule: `TST${Date.now()}`,
            password: 'TestPass123!',
            role: 'student',
            status: 'Active'
        };

        if (defaultData.role === 'student' || overrides.role === 'student') {
            defaultData.faculty = 'Engineering';
            defaultData.program = 'Computer Engineering';
        }

        const userData = { ...defaultData, ...overrides };
        const user = await User.create(userData);
        const token = jwt.sign(
            { id: user._id, role: user.role },
            process.env.JWT_SECRET,
            { expiresIn: process.env.JWT_EXPIRES_IN }
        );

        return { user, token };
    }

    static async createStudent(overrides = {}) {
        const defaultData = {
            name: `Test Student ${Date.now()}`,
            email: `student${Date.now()}@test.com`,
            matricule: `STU${Date.now()}`,
            faculty: 'Engineering',
            program: 'Computer Engineering',
            password: 'Password123!',
            role: 'student',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createAdmin(overrides = {}) {
        const defaultData = {
            name: `Admin ${Date.now()}`,
            email: `admin${Date.now()}@test.com`,
            matricule: `ADM${Date.now()}`,
            password: 'AdminPass123!',
            role: 'admin',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createHOD(overrides = {}) {
        const defaultData = {
            name: `HOD ${Date.now()}`,
            email: `hod${Date.now()}@test.com`,
            matricule: `HOD${Date.now()}`,
            faculty: 'Engineering',
            program: 'Computer Engineering',
            password: 'HodPass123!',
            role: 'hod',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createManyStudents(count, overrides = {}) {
        const students = [];
        for (let i = 0; i < count; i++) {
            const student = await this.createStudent(overrides);
            students.push(student);
        }
        return students;
    }
}

module.exports = UserFactory;

#!/usr/bin/env node
// Supported via standard GitHub programming aids
/* global __dirname */
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const { execSync } = require('child_process');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const fs = require('fs');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const path = require('path');

function run(cmd) {
  // eslint-disable-next-line no-undef
  console.log(`[package] $ ${cmd}`);
  execSync(cmd, { stdio: 'inherit' });
}

function checkMetadata() {
  const pkgPath = path.resolve(__dirname, '../package.json');
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  if (!pkg.name || !pkg.version || !pkg.publisher) {
    throw new Error('package.jsonの必須フィールド(name, version, publisher)が不足しています');
  }
  // eslint-disable-next-line no-undef
  console.log('[package] package.json metadata OK');
}

function checkFileSize() {
  const distPath = path.resolve(__dirname, '../dist/extension.js');
  if (fs.existsSync(distPath)) {
    const size = fs.statSync(distPath).size;
    const maxSize = 5 * 1024 * 1024; // 5MB
    if (size > maxSize) {
      throw new Error(`バンドルサイズが大きすぎます: ${size} bytes`);
    }
    // eslint-disable-next-line no-undef
    console.log(`[package] extension.js size: ${size} bytes`);
  }
}

function createVsix() {
  run('npx vsce package');
}

function signVsix() {
  // 署名処理（将来用）
  // run('npx vsce sign ...');
}

checkMetadata();
checkFileSize();
createVsix();
signVsix();
// eslint-disable-next-line no-undef
console.log('[package] Packaging completed.');

