function formatDateTime(datetimeLocalValue) {
    const date = new Date(datetimeLocalValue);

    const options = { month: '2-digit', day: '2-digit', year: 'numeric' };
    const formattedDate = date.toLocaleDateString('en-US', options);

    let hours = date.getHours();
    const minutes = date.getMinutes().toString().padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;

    const formattedTime = `${hours}:${minutes} ${ampm}`;

    return ` ${formattedTime} - ${formattedDate}`;
}

const TWO_WEEKS_MS = 14 * 24 * 60 * 60 * 1000;
const now = Date.now();

finishedHomework = finishedHomework.filter(item => {
    if (!item.completedAt) return true;
    const completedTime = new Date(item.completedAt).getTime();
    return now - completedTime <= TWO_WEEKS_MS;
});

localStorage.setItem('finishedHomework', JSON.stringify(finishedHomework));

import {Component, createRef, h} from '../../node_modules/preact/dist/preact.module.js'
import htm from '../../node_modules/htm/dist/htm.module.js'
import Cropper from '../../node_modules/cropperjs/dist/cropper.esm.js'
import Compressor from '../../node_modules/compressorjs/dist/compressor.esm.js'
import Format from "../App/Format.js"

const html = htm.bind(h)

/**
 * A file upload component
 *
 * Upload a single or multiple files. Crop, rotate, compress images.
 *
 * To get the files data, simply create a reference and call this.fileUploadRef.getFilesData().
 *
 * The main component was Designed with routine coding tools-4o in 15-20 tries. But code is understandable,
 * only a bit of black magic. This was extended, and so we got here in just a few hours.
 */
export default class FileUpload extends Component {
    constructor() {
        super();
        this.state = {
            files: [],
            cropping: false,
            currentFileIndex: null,
            croppedDataUrl: null,
            isDragging: false
        };
        this.dropzoneRef = createRef();
        this.fileInputRef = createRef();
        this.cropperImageRef = createRef();
        this.cropper = null;
    }

    handleDragEnter = (event) => {
        event.preventDefault();
        this.setState({ isDragging: true });
    };

    handleDragLeave = (event) => {
        event.preventDefault();
        this.setState({ isDragging: false });
    };

    handleDrop = (event) => {
        event.preventDefault();
        const files = Array.from(event.dataTransfer.files);
        this.processFiles(files);
    };

    handleFileSelect = (event) => {
        const files = Array.from(event.target.files);
        this.processFiles(files);
    };

    openFileDialog = () => {
        if (this.fileInputRef.current) {
            this.fileInputRef.current.click();
        }
    };

    processFiles = (files) => {
        if (!this.props.multiple) {
            files = files.slice(0, 1);
        }
        this.setState({ files: [...this.state.files, ...files], isDragging: false }, () => {
            if (this.state.files.length === 1 && files[0].type.startsWith('image/') && this.props.enableCropping) {
                this.startCropping(0);
            } else {
                this.callOnFileProp()
            }
        });
    };

    startCropping = (index) => {
        const file = this.state.files[index];
        const reader = new FileReader();
        reader.onload = (event) => {
            this.setState({
                currentFileIndex: index,
                cropping: true,
                croppedDataUrl: event.target.result
            }, this.initializeCropper);
        };
        reader.readAsDataURL(file);
    };

    initializeCropper = () => {
        const aspectRatio = this.props.aspectRatio ? this.parseAspectRatio(this.props.aspectRatio) : NaN;
        const image = this.cropperImageRef.current;
        this.cropper = new Cropper(image, {
            aspectRatio,
            viewMode: 1,
            rotatable: true,
            background: true,
            modal: true,
            autoCropArea: 1,
            responsive: true,
            guides: true,
        });
    };

    parseAspectRatio = (ratio) => {
        const [width, height] = ratio.split(':').map(Number);
        return width / height;
    };

    applyCrop = () => {
        const canvas = this.cropper.getCroppedCanvas();
        canvas.toBlob((blob) => {
            let currentFileIndex = this.state.currentFileIndex
            let originalFile = this.state.files[currentFileIndex];
            const croppedFile = new File([blob], originalFile.name, { type: originalFile.type });
            this.compressAndAddFile(croppedFile, currentFileIndex);
        });
    };

    callOnFileProp = () => {
        // Call onFile prop if set and pass files object
        if(this.props.onFile) {
            this.getFilesData()
                .then(data => {
                    this.props.onFile(data)
                })
        }
    }


    compressAndAddFile = (file, index) => {
        new Compressor(file, {
            quality: 0.8,
            maxWidth: this.props.maxWidth || Infinity,
            maxHeight: this.props.maxHeight || Infinity,
            success: (compressedFile) => {
                const files = [...this.state.files];
                files[index] = compressedFile;

                this.cropper.destroy();
                this.setState({ files: files, cropping: false, croppedDataUrl: null, currentFileIndex: null }, () => {
                    this.callOnFileProp()
                });
            }
        });
    };

    removeFile = (index) => {
        const files = this.state.files.filter((_, i) => i !== index);
        this.setState({files}, () => {
            // Since files changed also notify parent
            this.callOnFileProp()
        });
    };

    // Convert file to base64 string
    fileToBase64 = (file) => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = () => resolve(reader.result);
            reader.onerror = (error) => reject(error);
        });
    };

    // Get all files' details
    getFilesData = async () => {
        return await Promise.all(this.state.files.map(async (file) => {
            const base64 = await this.fileToBase64(file);
            return {
                filename: file.name,
                extension: file.name.split('.').pop().toLowerCase(),
                size: file.size,
                type: file.type,
                last_modified: new Date(file.lastModified).toISOString(),
                base64
            };
        }));
    };

    render(props, state, context) {
        let thumbnail_size = 50
        if(!this.props.multiple) {
            thumbnail_size = 100
        }

        return html`
            <div>
                ${(this.props.multiple || (!this.props.multiple && this.state.files.length < 1)) && html`
                    <div class="dropzone border border-2 rounded p-4 mb-3 d-flex flex-column justify-content-center align-items-center position-relative"
                         ref=${this.dropzoneRef}
                         onDrop=${this.handleDrop}
                         onDragEnter=${this.handleDragEnter}
                         onDragOver=${(e) => e.preventDefault()}
                         onDragLeave=${this.handleDragLeave}
                         style=${this.state.isDragging ? 'background: rgba(255, 255, 255, 0.2)' : ''}>
                        <input type="file"
                               multiple=${this.props.multiple}
                               accept=${this.props.accept}
                               onChange=${this.handleFileSelect}
                               ref=${this.fileInputRef}
                               class="form-control d-none" />
                        <div class="mb-2">
                            ${this.props.multiple ? html`Drag and drop files here` : html`Drag and drop file here`}
                        </div>
                        <div>
                            <button type="button" class="btn btn-primary btn-icon" onClick=${this.openFileDialog}>
                                <span class="material-symbols-outlined me-2">upload</span>
                                ${this.props.multiple ? html`Select Files` : html`Select File`}
                            </button>
                        </div>
                    </div>
                `}
                <div class="list-group">
                    ${this.state.files.map((file, index) => html`
                        <div class="list-group-item d-flex align-items-center justify-content-between">
                            <div class="me-2 d-flex align-items-center">
                                ${file.type.startsWith('image/') ? html`
                                    <img src=${URL.createObjectURL(file)} alt="Thumbnail" class="me-3 rounded" 
                                         style=${"width: " + thumbnail_size + "px; height: " + thumbnail_size + "px; object-fit: cover;"} />
                                ` : html`
                                    <span class="material-symbols-outlined me-4" style="font-size: 2.75rem">
                                        ${this.getSymbolForFileType(file.type)}
                                    </span>
                                `}

                                <div>
                                ${file.name}<br /><span class="text-muted">${Format.Bytes(file.size)}</span>
                                </div>
                            </div>

                            <div class="btn-group">
                                ${file.type.startsWith('image/') && this.props.enableCropping && !this.state.cropping && html`
                                    <button class="btn btn-icon btn-primary" title="Edit and Crop Image" 
                                            onClick=${() => this.startCropping(index)}>
                                        <span class="material-symbols-outlined text-white">tune</span>
                                    </button>
                                `}

                                <button class="btn btn-icon btn-danger" title="Remove" 
                                        onClick=${() => this.removeFile(index)}>
                                    <span class="material-symbols-outlined text-white">delete</span>
                                </button>
                            </div>
                        </div>
                    `)}
                </div>
                ${this.state.cropping && html`
                    <div class="position-fixed top-50 start-50 translate-middle card card-body shadow-lg p-3" style="z-index: 1050;">
                        <img ref=${this.cropperImageRef} src=${this.state.croppedDataUrl} alt="Cropping Image" class="w-100" />

                        <div class="d-flex align-items-center justify-content-between mt-3">
                            <div>
                                <div class="btn-group me-3">
                                    <button class="btn btn-icon btn-secondary" title="Zoom Out"
                                            onClick=${(e) => { e.preventDefault(); this.cropper.zoom(-0.1) }}>
                                        <span class="material-symbols-outlined">zoom_out</span>
                                    </button>
                                    <button class="btn btn-icon btn-secondary" title="Zoom In"
                                            onClick=${(e) => { e.preventDefault(); this.cropper.zoom(0.1) }}>
                                        <span class="material-symbols-outlined">zoom_in</span>
                                    </button>
                                </div>
                                <div class="btn-group me-3">
                                    <button class="btn btn-icon btn-secondary" title="Rotate 90° counterclockwise"
                                            onClick=${(e) => { e.preventDefault(); this.cropper.rotate(-90) }}>
                                        <span class="material-symbols-outlined">rotate_left</span>
                                    </button>
                                    <button class="btn btn-icon btn-secondary" title="Rotate 90° clockwise"
                                            onClick=${(e) => { e.preventDefault(); this.cropper.rotate(90) }}>
                                        <span class="material-symbols-outlined">rotate_right</span>
                                    </button>
                                    <button class="btn btn-icon btn-secondary" title="Mirror horizontally"
                                            onClick=${(e) => { e.preventDefault(); if(this.cropper.getImageData().scaleX == 1) { this.cropper.scaleX(-1) } else { this.cropper.scaleX(1) }  }}>
                                        <span class="material-symbols-outlined">swap_horiz</span>
                                    </button>
                                    <button class="btn btn-icon btn-secondary" title="Mirror vertically"
                                            onClick=${(e) => { e.preventDefault(); if(this.cropper.getImageData().scaleY == 1) { this.cropper.scaleY(-1) } else { this.cropper.scaleY(1) } }}>
                                        <span class="material-symbols-outlined">swap_vert</span>
                                    </button>
                                </div>
                            </div>
                            <div>
                                <button class="btn btn-primary btn-icon ms-auto" 
                                        onClick=${(e) => {e.preventDefault(); e.currentTarget.disabled = true; this.applyCrop()}}>
                                    <span class="material-symbols-outlined me-2">save</span>
                                    Apply Changes</button>
                            </div>
                        </div>


                    </div>
                `}
            </div>
        `;
    }

    getSymbolForFileType(fileType) {
        const fileTypeMapping = {
            'application/pdf': 'picture_as_pdf',
            'text/plain': 'description',
            'application/zip': 'folder_zip',
            'application/msword': 'description',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'description',
            'application/vnd.ms-excel': 'table_chart',
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'table_chart',
            'application/vnd.ms-powerpoint': 'slideshow',
            'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'slideshow',
            'text/csv': 'grid_on',
            'video/*': 'movie', // wildcard for all video types
            'audio/*': 'music_note', // wildcard for all audio types
            'image/*': 'image', // wildcard for all image types
            'text/*': 'description' // wildcard for all text types
        };

        // Check for exact match first
        if (fileTypeMapping[fileType]) {
            return fileTypeMapping[fileType];
        }

        // Check for wildcard match
        const [type] = fileType.split('/');
        const wildcardType = `${type}/*`;
        if (fileTypeMapping[wildcardType]) {
            return fileTypeMapping[wildcardType];
        }

        // Default icon if no match is found
        return 'draft';
    }
}

// Aided with basic GitHub coding tools
import React, { useState, useRef, useEffect, useCallback } from "react";

const BookCard = ({ book, onUpdateProgress, onDelete }) => {
  // 詳細表示用のポップアップ状態
  const [showDetails, setShowDetails] = useState(false);
  // 現在のページ数入力値の状態管理
  const [currentPageValue, setCurrentPageValue] = useState(book.currentPage);
  // 入力フィールドへの参照
  const pageInputRef = useRef(null);
  // 書籍データのローカルコピー
  const [localBook, setLocalBook] = useState(book);

  // propsのbookが変更されたらlocalBookも更新
  useEffect(() => {
    setLocalBook(book);
    setCurrentPageValue(book.currentPage);
  }, [book]);

  // 進捗パーセンテージを計算
  const calculateProgress = (currentPage, totalPages) => {
    if (!totalPages) return 0;
    return Math.round((currentPage / totalPages) * 100);
  };

  // 日付を整形する関数
  const formatDate = (dateString) => {
    if (!dateString) return "未設定";
    const date = new Date(dateString);
    return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
  };
  // ポップアップを閉じる前に状態を再確認（useCallbackでメモ化）
  const handleClosePopup = useCallback(async () => {
    // 現在のページ数が総ページ数に達していたら、サーバーから最新データを取得する
    if (currentPageValue >= book.totalPages) {
      try {
        // サーバーから最新の状態を取得するために0ページ更新を実行（データ取得のみ）
        const result = await onUpdateProgress(book.id, currentPageValue);
        if (result && result.success && result.book) {
          setLocalBook(result.book);
        }
      } catch (err) {
        console.error("状態確認エラー:", err);
      }
    }
    setShowDetails(false);
  }, [
    book.id,
    book.totalPages,
    currentPageValue,
    onUpdateProgress,
    setLocalBook,
    setShowDetails,
  ]);

  // ポップアップの外側クリックでポップアップを閉じる
  const handleOutsideClick = (e) => {
    // イベントがポップアップの背景からのものであれば、閉じる
    if (e.target.className === "book-details-popup-overlay") {
      handleClosePopup();
    }
  };
  // ESCキーでポップアップを閉じる処理
  React.useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") {
        handleClosePopup();
      }
    };

    if (showDetails) {
      // ポップアップが表示されている場合のみイベントリスナーを追加
      window.addEventListener("keydown", handleEsc);
    }

    return () => {
      window.removeEventListener("keydown", handleEsc);
    };
  }, [showDetails, handleClosePopup]);
  // プラスボタン処理関数
  const handleIncrement = async () => {
    // 現在のページ数を1増やす（最大は総ページ数まで）
    const newPage = Math.min(Number(currentPageValue) + 1, book.totalPages);
    setCurrentPageValue(newPage);

    try {
      // 進捗を更新
      const result = await onUpdateProgress(book.id, newPage);

      // 更新に成功し、結果に書籍データが含まれている場合はローカル状態も更新
      if (result && result.success && result.book) {
        setLocalBook(result.book);

        // 現在のページが総ページ数に達したら、ポップアップを再レンダリングして完読表示を更新
        if (newPage >= book.totalPages) {
          // 少し遅延させて再レンダリングを確実にする
          setTimeout(() => {
            setShowDetails(false);
            setShowDetails(true);
          }, 100);
        }
      }
    } catch (err) {
      console.error("進捗更新エラー:", err);
    }

    // 入力フィールドの値も更新
    if (pageInputRef.current) {
      pageInputRef.current.value = newPage;
    }
  };

  // マイナスボタン処理関数
  const handleDecrement = async () => {
    const newPage = Math.max(Number(currentPageValue) - 1, 0);
    setCurrentPageValue(newPage);

    try {
      // 進捗を更新
      const result = await onUpdateProgress(book.id, newPage);

      // 更新に成功し、結果に書籍データが含まれている場合はローカル状態も更新
      if (result && result.success && result.book) {
        setLocalBook(result.book);
      }
    } catch (err) {
      console.error("進捗更新エラー:", err);
    }

    // 入力フィールドの値も更新
    if (pageInputRef.current) {
      pageInputRef.current.value = newPage;
    }
  };
  // 入力フィールドの変更ハンドラ
  const handleInputChange = async (e) => {
    const value = parseInt(e.target.value, 10) || 0;
    setCurrentPageValue(value);

    try {
      // 進捗を更新
      const result = await onUpdateProgress(book.id, value);

      // 更新に成功し、結果に書籍データが含まれている場合はローカル状態も更新
      if (result && result.success && result.book) {
        setLocalBook(result.book);

        // 現在のページが総ページ数に達したら、ポップアップを再レンダリングして完読表示を更新
        if (value >= book.totalPages) {
          // 少し遅延させて再レンダリングを確実にする
          setTimeout(() => {
            setShowDetails(false);
            setShowDetails(true);
          }, 100);
        }
      }
    } catch (err) {
      console.error("進捗更新エラー:", err);
    }
  };

  // 最小限の情報表示カード
  const renderMinimalCard = () => {
    const progressPercentage = calculateProgress(
      localBook.currentPage,
      localBook.totalPages
    );

    return (
      <div className="book-card" onClick={() => setShowDetails(true)}>
        <h3 className="book-title">{localBook.title}</h3>

        <div className="book-progress">
          <div className="progress-bar">
            <div
              className="progress-fill"
              style={{
                width: `${progressPercentage}%`,
              }}
            ></div>
          </div>{" "}
          <p>
            <span>
              {localBook.currentPage} / {localBook.totalPages} ページ
            </span>
            <span>{progressPercentage}%</span>
          </p>
        </div>
      </div>
    );
  };

  // 詳細情報を表示するポップアップ
  const renderDetailsPopup = () => (
    <div className="book-details-popup-overlay" onClick={handleOutsideClick}>
      <div className="book-details-popup">
        {" "}
        <button className="close-popup-btn" onClick={handleClosePopup}>
          ×
        </button>{" "}
        <h2 className="book-title">{localBook.title}</h2>
        <p className="book-author">著者: {localBook.author}</p>
        <div className="book-progress">
          <p>
            {localBook.currentPage} / {localBook.totalPages} ページ (
            {calculateProgress(localBook.currentPage, localBook.totalPages)}%)
          </p>
          <div className="progress-bar">
            <div
              className="progress-fill"
              style={{
                width: `${calculateProgress(
                  localBook.currentPage,
                  localBook.totalPages
                )}%`,
              }}
            ></div>
          </div>
        </div>{" "}
        <div className="book-dates">
          <p className="text-muted">
            読書開始: {formatDate(localBook.startDate)}
          </p>
          <p className="text-muted">
            最終更新: {formatDate(localBook.lastUpdateDate)}
          </p>
        </div>
        <div className="progress-update">
          <label htmlFor={`progress-${localBook.id}`}>現在のページ:</label>
          <div className="progress-input">
            <button
              className="page-control-btn page-decrement-btn"
              onClick={handleDecrement}
              disabled={currentPageValue <= 0}
            >
              －
            </button>
            <input
              type="number"
              id={`progress-${localBook.id}`}
              min="0"
              max={localBook.totalPages}
              defaultValue={localBook.currentPage}
              onChange={handleInputChange}
              ref={pageInputRef}
            />
            <button
              className="page-control-btn page-increment-btn"
              onClick={handleIncrement}
              disabled={currentPageValue >= localBook.totalPages}
            >
              ＋
            </button>
            <span>/ {localBook.totalPages}</span>
          </div>
        </div>
        {localBook.memo && (
          <div className="book-memo">
            <strong>メモ:</strong>
            <p>{localBook.memo}</p>
          </div>
        )}
        <div className="book-actions">
          <button
            className="btn btn-danger"
            onClick={() => onDelete(localBook.id)}
          >
            削除
          </button>{" "}
          <button className="btn" onClick={handleClosePopup}>
            閉じる
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <>
      {/* 最小限の情報カードを表示 */}
      {renderMinimalCard()}

      {/* 詳細ポップアップ（表示フラグがtrueの場合のみ表示） */}
      {showDetails && renderDetailsPopup()}
    </>
  );
};

export default BookCard;

