    const template = document.createElement('template');
    template.innerHTML = `
      <style>
        nav {
            border-bottom: 1px solid grey;
        }
        nav > ul {
            list-style: none;
            display: flex;
            flex-wrap: wrap;
            justify-content: baseline;
