    data: PropTypes.array.isRequired,
    totals: PropTypes.shape({
        TotalColleges: PropTypes.number.isRequired,
        TotalTeams: PropTypes.number.isRequired,
        TotalTeamMembers: PropTypes.number.isRequired,
    }).isRequired,
};

export { ReportGridOne };

